import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {spawnSync,execFileSync} from 'node:child_process';import {fileURLToPath} from 'node:url';
const repo=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..'),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const packages=['agency-off-native-transport-forward-20261015','agency-fixed-approval-policy-support-20261015'];
const measured=[];for(const name of packages){const p='docs/healthroster-build/proposals/'+name,m=JSON.parse(fs.readFileSync(path.join(repo,p,'REVIEW_MANIFEST.json')));for(const e of m.entries){const raw=fs.readFileSync(path.join(repo,p,e.path));assert.equal(sha(raw),e.sha256);assert.equal(raw.length,e.bytes);}measured.push({package:p,files:m.entries.length+1,manifest_sha256:sha(fs.readFileSync(path.join(repo,p,'REVIEW_MANIFEST.json'))),checks_sha256:sha(fs.readFileSync(path.join(repo,p,'SOURCE_CHECKS.json')))});}
const off=path.join(repo,'docs/healthroster-build/proposals/'+packages[0]),r=JSON.parse(fs.readFileSync(path.join(off,'OFF_AGENCY_COMPLETE_REVERSES.json')));
const whitespace=s=>s.replaceAll('\r\n','\n').split('\n').filter(line=>/[ \t]+$/.test(line));
const whitespaceProof=[];for(const e of r.reverses){let after=fs.readFileSync(path.join(off,e.output),'utf8'),before=fs.readFileSync(path.join(off,'before',e.output+'.txt'),'utf8');assert.equal(sha(after),e.after_sha256);let reverse=after;for(const h of [...e.hunks].reverse())reverse=reverse.replace(h.after,()=>h.before);assert.equal(reverse,before);const a=whitespace(after),b=whitespace(before);assert.deepEqual(a,b,e.output+' introduced whitespace');whitespaceProof.push({output:e.output,full_before_trailing_lines:b.length,full_after_trailing_lines:a.length,introduced_trailing_lines:0,before_sha256:e.before_sha256,after_sha256:e.after_sha256});}
const rawCheck=spawnSync('git',['diff','--cached','--check'],{cwd:repo,encoding:'utf8',maxBuffer:96e6});assert.ok([0,1,2].includes(rawCheck.status));const rawFindings=(rawCheck.stdout.match(/^[^\r\n]+: (?:trailing whitespace|new blank line at EOF)\./gm)||[]).length;
const proof={source_only:true,native:false,mount_ready:false,parent_head:execFileSync('git',['rev-parse','HEAD'],{cwd:repo,encoding:'utf8'}).trim(),packages:measured,
 full_unique_hunks:r.reverses.reduce((n,x)=>n+x.hunks.length,0),raw_diff_check_exit:rawCheck.status,raw_diff_check_findings:rawFindings,raw_whitespace_pass:false,complete_whitespace_provenance:whitespaceProof,
 source_private_helper:'private.weekly_source_off_rule_agency_parent_v1(text,jsonb,uuid,boolean)',service_or_browser_grant_added:false,
 static_closure:JSON.parse(fs.readFileSync(path.join(off,'CURRENT_OFF_LITERAL_IMPORT_CLOSURE.json'))).objects,
 independent_review:'PENDING',compiled_contract_sha256:null,source_tree_seal:null,other_frozen_packages_preserved:true};
fs.writeFileSync(path.join(repo,'docs/healthroster-build/AGENCY_POLICY_OFF_SOURCE_BACKUP_CHECKPOINT_15102026.json'),JSON.stringify(proof,null,2)+'\n');
console.log(JSON.stringify({source_only:true,files:measured.reduce((n,p)=>n+p.files,0),full_hunks:proof.full_unique_hunks,raw_diff_findings:rawFindings,raw_whitespace_pass:false,introduced_trailing_lines:0,runtime_index_sha256:r.reverses.find(x=>x.output==='102_complete_current_index_with_actual_off_agency.js').after_sha256}));
